<?php defined('APP_BOOTSTRAPPED')||exit;$rows=dball('SELECT v.*,u.full_name,u.email,u.status user_status FROM vendors v JOIN users u ON u.id=v.user_id ORDER BY FIELD(v.status,"pending","approved","rejected"),v.id DESC'); ?>
<section class="container section page-top"><div class="dash-layout"><?php require __DIR__.'/../partials/side_nav.php';?><div class="dash-main"><div class="eyebrow">SHOP APPROVAL</div><h1 class="page-title">Duyệt <em>gian hàng</em></h1><p class="muted">Người dùng nộp hồ sơ → Admin duyệt → tài khoản được cấp vai trò Vendor.</p>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Shop</th><th>Chủ gian hàng</th><th>Địa chỉ</th><th>Trạng thái</th><th>Duyệt</th></tr></thead><tbody><?php foreach($rows as $v):?><tr><td><strong><?=h($v['shop_name'])?></strong><small class="table-sub"><?=h($v['printer_capacity']??'')?></small></td><td><?=h($v['full_name'])?><small class="table-sub"><?=h($v['email'])?></small></td><td><?=h($v['address'])?></td><td><span class="status-pill"><?=h($v['status'])?></span></td><td class="action-cell"><form method="post" action="<?=h(url('admin_vendors'))?>"><?php csrf_field();?><input type="hidden" name="action" value="admin_vendor_review"><input type="hidden" name="id" value="<?=$v['id']?>"><input type="hidden" name="status" value="approved"><button class="btn btn-primary btn-sm">Duyệt</button></form><form method="post" action="<?=h(url('admin_vendors'))?>"><?php csrf_field();?><input type="hidden" name="action" value="admin_vendor_review"><input type="hidden" name="id" value="<?=$v['id']?>"><input type="hidden" name="status" value="rejected"><button class="btn btn-ghost btn-sm">Từ chối</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section>
